/**
 * Rainbow Terraces — the Blender-built models (rainbow-terraces-models.js, generated by
 * scripts/blender/rainbow_terraces_models.py) and what the theme builds of them
 * (rainbow-terraces-model-build.js): the module decodes; every model is indexed, finite and wound
 * outward, its normals on the side its triangles face; a stone kind never changes across a
 * triangle; the baked occlusion and moss are weights; a tree's levels get leaner; a grove grows
 * the same from the same seed, every trunk running on down below its spot; the balustrade keeps
 * the old parapet's place, height and footprint, and stays clear of the eye.
 */
import { statSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import * as THREE from 'three/webgpu';
import { RAINBOW_TERRACES_MODELS as MODELS } from '../../src/themes/rainbow-terraces/rainbow-terraces-models.js';
import {
    BALUSTRADE, BALUSTRADE_LEVELS, TREE_FOOT, TREE_KINDS, TREE_LEVELS, balustradeGeometry, treeGeometry, treeModel,
    treeVariants,
} from '../../src/themes/rainbow-terraces/rainbow-terraces-model-build.js';
import {
    MAT, PARAPET, buildGrove, buildParapet, groveDetail, parapetDetail,
} from '../../src/themes/rainbow-terraces/rainbow-terraces-isles.js';
import { QUALITY, QUALITY_NAMES } from '../../src/themes/rainbow-terraces/rainbow-terraces-quality.js';
import { REST_RIG } from '../../src/themes/rainbow-terraces/rainbow-terraces-frame.js';

const STONE_ATTRIBUTES = ['aAO', 'aBed', 'aCrown', 'aMat', 'aMoss', 'normal', 'position'];
const KINDS = Object.values(MAT);
const trianglesOf = (g) => g.index.count / 3;

/** Every packed model of the module: [name, model, quant]. */
function packedModels() {
    const out = [];
    const B = MODELS.balustrade;
    ['ledge', 'paving', 'rail', 'pier'].forEach((name) => out.push([`balustrade.${name}`, B[name], B.quant]));
    B.baluster.forEach((model, level) => out.push([`balustrade.baluster[${level}]`, model, B.quant]));
    TREE_KINDS.forEach((kind) => MODELS.trees[kind].forEach((levels, variant) => levels.forEach((model, level) => {
        out.push([`trees.${kind}[${variant}][${level}]`, model, MODELS.trees.quant]);
    })));
    return out;
}

const bytesOf = (text) => Uint8Array.from(atob(text), (c) => c.charCodeAt(0));

// The connected pieces of a geometry (points welded at a millimetre, as the isles' own test welds
// them): a closed piece's every edge is walked once each way, and it faces out when its signed
// volume is positive.
function pieces(g) {
    const pos = g.attributes.position;
    const ids = new Map();
    const id = Array.from({ length: pos.count }, (_, v) => {
        const k = `${Math.round(pos.getX(v) * 1e3)},${Math.round(pos.getY(v) * 1e3)},${Math.round(pos.getZ(v) * 1e3)}`;
        if (!ids.has(k)) ids.set(k, ids.size);
        return ids.get(k);
    });
    const parent = Array.from({ length: ids.size }, (_, i) => i);
    const find = (i) => {
        let r = i;
        while (parent[r] !== r) r = parent[r];
        parent[i] = r;
        return r;
    };
    const tris = [];
    for (let t = 0; t < g.index.count; t += 3) {
        const tri = [g.index.getX(t), g.index.getX(t + 1), g.index.getX(t + 2)];
        if (new Set(tri.map((v) => id[v])).size === 3) tris.push(tri);
    }
    tris.forEach(([a, b, c]) => {
        parent[find(id[a])] = find(id[b]);
        parent[find(id[b])] = find(id[c]);
    });
    const out = new Map();
    const P = (v) => new THREE.Vector3().fromBufferAttribute(pos, v);
    tris.forEach((tri) => {
        const r = find(id[tri[0]]);
        if (!out.has(r)) out.set(r, { edges: new Map(), volume: 0, kind: g.attributes.aMat.getX(tri[0]) });
        const p = out.get(r);
        p.volume += P(tri[0]).dot(P(tri[1]).cross(P(tri[2]))) / 6;
        tri.forEach((v, k) => {
            const e = `${id[v]}>${id[tri[(k + 1) % 3]]}`;
            p.edges.set(e, (p.edges.get(e) || 0) + 1);
        });
    });
    return [...out.values()].map(({ edges, volume, kind }) => ({
        closed: [...edges.keys()].every((e) => edges.has(e.split('>').reverse().join('>'))),
        consistent: [...edges.values()].every((n) => n === 1),
        volume,
        kind,
    }));
}

/** The share of triangle corners whose normal lies on the side its triangle faces. */
function normalsAgree(g) {
    const pos = g.attributes.position;
    const nrm = g.attributes.normal;
    const A = new THREE.Vector3();
    const B = new THREE.Vector3();
    const C = new THREE.Vector3();
    const N = new THREE.Vector3();
    let agree = 0;
    let corners = 0;
    for (let t = 0; t < g.index.count; t += 3) {
        const tri = [g.index.getX(t), g.index.getX(t + 1), g.index.getX(t + 2)];
        A.fromBufferAttribute(pos, tri[0]);
        B.fromBufferAttribute(pos, tri[1]).sub(A);
        C.fromBufferAttribute(pos, tri[2]).sub(A);
        B.cross(C).normalize();
        for (const v of tri) {
            corners += 1;
            if (N.fromBufferAttribute(nrm, v).dot(B) > 0) agree += 1;
        }
    }
    return agree / corners;
}

/** What every stone geometry must be, whatever it is of. */
function expectStone(g, label) {
    expect(Object.keys(g.attributes).sort(), label).toEqual(STONE_ATTRIBUTES);
    expect(g.index, label).toBeTruthy();
    expect(g.index.count % 3, label).toBe(0);
    const { count } = g.attributes.position;
    expect(count, label).toBeGreaterThan(0);
    STONE_ATTRIBUTES.forEach((name) => {
        expect(g.attributes[name].count, `${label} ${name}`).toBe(count);
        expect(Array.from(g.attributes[name].array).every(Number.isFinite), `${label} ${name}`).toBe(true);
    });
    let top = 0;
    for (let i = 0; i < g.index.count; i++) top = Math.max(top, g.index.getX(i));
    expect(top, label).toBeLessThan(count);
    const {
        aMat, aAO, aMoss, normal,
    } = g.attributes;
    for (let v = 0; v < count; v++) {
        expect(KINDS, label).toContain(aMat.getX(v));
        expect(aAO.getX(v), label).toBeGreaterThanOrEqual(0);
        expect(aAO.getX(v), label).toBeLessThanOrEqual(1);
        expect(aMoss.getX(v), label).toBeGreaterThanOrEqual(0);
        expect(aMoss.getX(v), label).toBeLessThanOrEqual(1);
        expect(Math.hypot(normal.getX(v), normal.getY(v), normal.getZ(v)), label).toBeCloseTo(1, 4);
    }
    // A stone kind names whole pieces: it never changes across a triangle (an id interpolated
    // from one kind to another would sweep through the kinds between them).
    for (let t = 0; t < g.index.count; t += 3) {
        const kind = aMat.getX(g.index.getX(t));
        expect(aMat.getX(g.index.getX(t + 1)), label).toBe(kind);
        expect(aMat.getX(g.index.getX(t + 2)), label).toBe(kind);
    }
}

describe('Rainbow Terraces models: the module', () => {
    it('decodes: every model\'s arrays are as long as it says and its kinds cover its vertices', () => {
        const models = packedModels();
        expect(models.length).toBeGreaterThan(15);
        models.forEach(([name, model, quant]) => {
            expect(quant, name).toBeGreaterThan(0);
            const positions = new Int16Array(bytesOf(model.positions).buffer);
            const index = new Uint16Array(bytesOf(model.index).buffer);
            expect(positions.length, name).toBe(model.vertexCount * 3);
            expect(bytesOf(model.normals).length, name).toBe(model.vertexCount * 3);
            expect(bytesOf(model.ao).length, name).toBe(model.vertexCount);
            if (model.moss) expect(bytesOf(model.moss).length, name).toBe(model.vertexCount);
            expect(index.length, name).toBe(model.triangleCount * 3);
            expect(Math.max(...index), name).toBeLessThan(model.vertexCount);
            // The kinds: runs of vertices end to end, each a stone kind the theme shades.
            let next = 0;
            model.kinds.forEach(([kind, first, n]) => {
                expect(KINDS, name).toContain(kind);
                expect(first, name).toBe(next);
                expect(n, name).toBeGreaterThan(0);
                next = first + n;
            });
            expect(next, name).toBe(model.vertexCount);
        });
        // The ivy: whole rows of leaves and stems, every stem ended.
        const { ivy } = MODELS.balustrade;
        expect(bytesOf(ivy.leaves).length).toBe(ivy.leafCount * 12);
        const stems = new Int16Array(bytesOf(ivy.stems).buffer);
        expect(stems.length % 4).toBe(0);
        expect(Array.from(stems.slice(-4))).toEqual([0, 0, 0, 0]);
        expect(ivy.leafShape.index.length % 3).toBe(0);
        expect(Math.max(...ivy.leafShape.index)).toBeLessThan(ivy.leafShape.points.length);
    });

    it('stays small enough to ship as source', () => {
        const module = '../../src/themes/rainbow-terraces/rainbow-terraces-models.js';
        expect(statSync(fileURLToPath(new URL(module, import.meta.url))).size).toBeLessThan(250 * 1024);
    });
});

describe('Rainbow Terraces models: the grove\'s trees', () => {
    const spot = (kind, size = 7) => [3, 40, -5, size, kind];

    it('builds every kind, shape and level as stone: indexed, finite, its leaf a closed skin that faces out', () => {
        TREE_KINDS.forEach((name, kind) => {
            expect(treeVariants(kind), name).toBeGreaterThanOrEqual(1);
            for (let variant = 0; variant < treeVariants(kind); variant++) {
                for (let level = 0; level < TREE_LEVELS; level++) {
                    const label = `${name} ${variant}/${level}`;
                    const g = buildGrove([spot(kind)], 41 + variant, level);
                    expectStone(g, label);
                    const kinds = new Set(Array.from(g.attributes.aMat.array));
                    expect(kinds.has(MAT.leaf), label).toBe(true);
                    // (Bark on a cypress and a pine; a shrub is all leaf.)
                    expect(kinds.has(MAT.iron), label).toBe(name !== 'shrub');
                    const closed = pieces(g).filter((p) => p.closed);
                    expect(closed.some((p) => p.kind === MAT.leaf), `${label}: a closed skin of leaf`).toBe(true);
                    closed.forEach((p) => {
                        expect(p.consistent, `${label}: a piece wound both ways`).toBe(true);
                        expect(p.volume, `${label}: a piece inside out`).toBeGreaterThan(0);
                    });
                    // (Foliage normals lean toward the whole form's: nearly all still on their face's side.)
                    expect(normalsAgree(g), label).toBeGreaterThan(0.97);
                    g.dispose();
                }
            }
        });
    });

    it('gets leaner level by level, and darker inside and under than on top', () => {
        TREE_KINDS.forEach((name, kind) => {
            for (let variant = 0; variant < treeVariants(kind); variant++) {
                const models = Array.from({ length: TREE_LEVELS }, (_, level) => treeModel(kind, variant, level));
                for (let level = 1; level < TREE_LEVELS; level++) {
                    const label = `${name} ${variant}/${level}`;
                    expect(models[level].triangles, label).toBeLessThan(models[level - 1].triangles * 0.6);
                }
                // The baked occlusion is a real one: the crown's top stands in the open, its lowest leaf in shade.
                const m = models[0];
                let high = -Infinity;
                let low = Infinity;
                let highAO = 0;
                let lowAO = 0;
                for (let v = 0; v < m.count; v++) {
                    if (m.mat[v] !== MAT.leaf) continue;
                    const y = m.position[v * 3 + 1];
                    if (y > high) { high = y; highAO = m.ao[v]; }
                    if (y < low) { low = y; lowAO = m.ao[v]; }
                }
                expect(highAO, `${name} ${variant}: its top`).toBeGreaterThan(0.85);
                expect(lowAO, `${name} ${variant}: its underside`).toBeLessThan(highAO - 0.25);
                expect(Math.min(...m.ao), `${name} ${variant}: never black`).toBeGreaterThanOrEqual(0.25);
            }
        });
    });

    it('stands every tree on its spot: the trunk within its foot and running on down below the spot', () => {
        for (const kind of [0, 1]) {
            for (const size of [5, 9]) {
                for (let variant = 0; variant < treeVariants(kind); variant++) {
                    for (let level = 0; level < TREE_LEVELS; level++) {
                        const [x, y, z] = spot(kind, size);
                        const label = `${TREE_KINDS[kind]} ${variant}/${level} size ${size}`;
                        const g = treeGeometry(spot(kind, size), {
                            level, variant, turn: 1.1, tall: 0.87, wide: 1.08,
                        });
                        const pos = g.attributes.position;
                        const mat = g.attributes.aMat;
                        let foot = Infinity;
                        let leafLow = Infinity;
                        for (let v = 0; v < pos.count; v++) {
                            if (mat.getX(v) === MAT.leaf) leafLow = Math.min(leafLow, pos.getY(v));
                            if (mat.getX(v) !== MAT.iron) continue;
                            foot = Math.min(foot, pos.getY(v));
                            // Under the turf (the spot is sunk 1.3 m into it) the trunk keeps within the
                            // foot the grove's spots are tested for: 0.12 of its size round the spot.
                            if (pos.getY(v) < y + 1.3) {
                                const off = Math.hypot(pos.getX(v) - x, pos.getZ(v) - z);
                                expect(off, label).toBeLessThanOrEqual(size * 0.12);
                            }
                        }
                        expect(foot, label).toBeLessThan(y - 0.5);
                        // The leaf starts over the foot: a trunk shows under it.
                        expect(leafLow, label).toBeGreaterThan(y + TREE_FOOT);
                        g.dispose();
                    }
                }
            }
        }
        // A shrub is a mound sunk into the turf: it reaches below its spot's turf line and stands over it.
        const [, y] = spot(2, 3.5);
        const shrub = treeGeometry(spot(2, 3.5), { tall: 0.7, wide: 0.75 });
        shrub.computeBoundingBox();
        expect(shrub.boundingBox.min.y).toBeLessThan(y + 1.3 - 0.4);
        expect(shrub.boundingBox.max.y).toBeGreaterThan(y + 1.3 + 0.5);
        shrub.dispose();
    });

    it('grows a grove the same from the same seed, another from another, leaner at a leaner level', () => {
        const spots = [
            [0, 10, 0, 7, 0], [12, 11, -4, 6, 1], [-9, 9, 5, 3, 2], [20, 10, 8, 8.5, 0], [-20, 12, -9, 5.5, 1],
        ];
        const a = buildGrove(spots, 41, 0);
        const b = buildGrove(spots, 41, 0);
        STONE_ATTRIBUTES.forEach((name) => expect(b.attributes[name].array, name).toEqual(a.attributes[name].array));
        expect(b.index.array).toEqual(a.index.array);
        const other = buildGrove(spots, 43, 0);
        expect(Array.from(other.attributes.position.array)).not.toEqual(Array.from(a.attributes.position.array));
        const counts = [0, 1, 2].map((level) => {
            const g = buildGrove(spots, 41, level);
            const n = trianglesOf(g);
            g.dispose();
            return n;
        });
        expect(counts[1]).toBeLessThan(counts[0]);
        expect(counts[2]).toBeLessThan(counts[1]);
        // A spot's tree does not depend on the trees before it being of one kind or another.
        const swapped = buildGrove([[0, 10, 0, 7, 2], ...spots.slice(1)], 41, 0);
        const tail = (g, n) => Array.from(g.attributes.position.array.slice(-n));
        expect(tail(swapped, 300)).toEqual(tail(a, 300));
        [a, b, other, swapped].forEach((g) => g.dispose());
        // The tiers: the full trees from High up, the leaner ones below.
        expect(QUALITY_NAMES.map((q) => groveDetail(QUALITY[q]))).toEqual([1, 1, 1, 0, 0, 0]);
    });
});

describe('Rainbow Terraces models: the overlook\'s balustrade', () => {
    // The eye in the balustrade's own frame at rest in a 16:9 frame (measured in the world: the
    // corner is pinned 13 m off, under the frame's bottom-left).
    const EYE = new THREE.Vector3(0, 3.738, 12.451);

    it('builds as stone at every level: indexed, finite, its closed pieces facing out', () => {
        for (let level = 0; level < BALUSTRADE_LEVELS; level++) {
            const g = buildParapet(true, level);
            expectStone(g, `level ${level}`);
            const kinds = new Set(Array.from(g.attributes.aMat.array));
            expect([...kinds].sort()).toEqual([MAT.travertine, MAT.iron, MAT.masonry, MAT.leaf].sort());
            const closed = pieces(g).filter((p) => p.closed);
            // The rail, the plinth course, the two piers and their finials, the ledge's bed.
            expect(closed.length, `level ${level}`).toBeGreaterThanOrEqual(5);
            closed.forEach((p) => expect(p.volume, `level ${level}: a piece inside out`).toBeGreaterThan(0));
            expect(normalsAgree(g), `level ${level}`).toBeGreaterThan(0.995);
            g.dispose();
        }
        expect(trianglesOf(balustradeGeometry(0))).toBeLessThan(trianglesOf(balustradeGeometry(1)) * 0.8);
        expect(QUALITY_NAMES.map((q) => parapetDetail(QUALITY[q]))).toEqual([0, 0, 1, 1, 1, 1]);
    });

    it('keeps the parapet\'s place: its paving at y = 0, its top where the frame reads it, its old footprint', () => {
        const g = buildParapet(true, 1);
        g.computeBoundingBox();
        const { min, max } = g.boundingBox;
        // The top (the finial's crown) is what the world reads as the parapet's height.
        expect(g.userData.top).toBe(BALUSTRADE.top);
        expect(max.y).toBeCloseTo(BALUSTRADE.top, 2);
        expect(PARAPET.newel + 0.22).toBeCloseTo(BALUSTRADE.top, 9);
        // No taller than the blockout it replaces (1.72 m), on the same ledge (x −11..1.5, z −1.2..6).
        expect(BALUSTRADE.top).toBeLessThanOrEqual(1.72 + 1e-9);
        expect(min.x).toBeGreaterThan(-11.2);
        expect(max.x).toBeLessThan(1.9);
        expect(min.z).toBeGreaterThan(-1.9);
        expect(max.z).toBeLessThan(6.1);
        expect(min.y).toBeLessThan(-1.6);
        // The balusters stand where PARAPET says, between the rail's two piers.
        expect(PARAPET.balusters).toBe(BALUSTRADE.balusters);
        expect(PARAPET.pitch).toBe(BALUSTRADE.pitch);
        expect(BALUSTRADE.farPierX).toBeLessThan(BALUSTRADE.balusterX0 - (BALUSTRADE.balusters - 1) * BALUSTRADE.pitch);
        expect(BALUSTRADE.pierX).toBeGreaterThan(BALUSTRADE.balusterX0);
        // The paving: travertine facing the sky lies at the ledge's top, within a flag's unevenness.
        const pos = g.attributes.position;
        const nrm = g.attributes.normal;
        const mat = g.attributes.aMat;
        let flags = 0;
        for (let v = 0; v < pos.count; v++) {
            if (mat.getX(v) === MAT.travertine && nrm.getY(v) > 0.98 && pos.getY(v) > -0.05) {
                flags += 1;
                expect(Math.abs(pos.getY(v))).toBeLessThan(0.03);
            }
        }
        expect(flags).toBeGreaterThan(300);
        g.dispose();
    });

    it('comes no nearer the eye than the camera\'s near plane, at either level', () => {
        for (let level = 0; level < BALUSTRADE_LEVELS; level++) {
            const g = balustradeGeometry(level);
            const pos = g.attributes.position;
            const P = new THREE.Vector3();
            let nearest = Infinity;
            for (let v = 0; v < pos.count; v++) {
                nearest = Math.min(nearest, P.fromBufferAttribute(pos, v).distanceTo(EYE));
            }
            expect(nearest, `level ${level}`).toBeGreaterThan(REST_RIG.near * 2);
            g.dispose();
        }
    });

    it('grows its ivy as leaves that show the eye a face, on stems of bark', () => {
        const g = balustradeGeometry(1);
        const pos = g.attributes.position;
        const mat = g.attributes.aMat;
        const A = new THREE.Vector3();
        const B = new THREE.Vector3();
        const C = new THREE.Vector3();
        let leaves = 0;
        let shown = 0;
        let bark = 0;
        for (let t = 0; t < g.index.count; t += 3) {
            const a = g.index.getX(t);
            if (mat.getX(a) === MAT.iron) bark += 1;
            if (mat.getX(a) !== MAT.leaf) continue;
            leaves += 1;
            A.fromBufferAttribute(pos, a);
            B.fromBufferAttribute(pos, g.index.getX(t + 1)).sub(A);
            C.fromBufferAttribute(pos, g.index.getX(t + 2)).sub(A);
            // (The stone's material draws one side of a triangle: a leaf turned away is not seen.)
            if (B.cross(C).dot(EYE.clone().sub(A)) > 0) shown += 1;
        }
        const perLeaf = MODELS.balustrade.ivy.leafShape.index.length / 3;
        expect(leaves).toBe(MODELS.balustrade.ivy.leafCount * perLeaf);
        expect(shown / leaves).toBeGreaterThan(0.8);
        expect(bark).toBeGreaterThan(50);
        g.dispose();
    });
});
